suppressPackageStartupMessages({library(data.table);library(readxl)})
out<-'audit/20261011_all_groups_algorithm_audit/kla_tissues';rawroot<-'/Users/gzy2520/Desktop/Research/kla/data';release<-'deliverables/20261011_lactylation_ddr_tall_verified'
u<-fread(file.path(release,'tables/ddr_source_unit_values.csv'))[Dataset=='Lactylome (Kla)'&as.integer(sub('KLA31_','',GroupID))<=12]
cur<-fread(cmd=paste('gzip -dc',file.path(release,'inputs/ddr_protein_membership.csv.gz')))[Dataset=='Lactylome (Kla)'];cur<-merge(cur,unique(u[,.(PXD,SampleGroup,GroupID)]),by=c('PXD','SampleGroup'))
regex<-'^(?:[OPQ][0-9][A-Z0-9]{3}[0-9]|[A-NR-Z][0-9][A-Z][A-Z0-9]{2}[0-9](?:[A-Z0-9]{3}[0-9])?)$'
parse_new<-function(v){v<-unlist(strsplit(as.character(v),'[;,:]'));v<-trimws(v);v<-v[!is.na(v)&!grepl('^(REV__|CON__|DECOY|CONTAM)',v,ignore.case=TRUE)];v<-sub('^(sp|tr)\\|','',v);v<-sub('\\|.*$','',v);v<-sub('^NX_','',v);v<-sub('-[0-9]+$','',v);sort(unique(v[grepl(regex,v)]))}
parse_old<-function(v){v<-unlist(strsplit(as.character(v),'[;,]'));v<-trimws(v);v<-sub('^.*\\|([^|]+)\\|.*$','\\1',v);v<-sub('^([^|;]+)\\|.*$','\\1',v);v<-sub('^NX_','',v);v<-sub('-[0-9]+$','',v);sort(unique(v[!is.na(v)&grepl(regex,v)]))}
pos<-function(x){x<-suppressWarnings(as.numeric(x));is.finite(x)&x>0};flag<-function(x)tolower(trimws(as.character(x)))%in%c('+','1','true','yes','y')
g<-fread('data/publication_input/human_ddr_go_annotations.tsv');ddr<-parse_new(g[(is.na(`TAXON ID`)|`TAXON ID`==9606)&`GENE PRODUCT DB`=='UniProtKB'&!grepl('(^|\\|)NOT($|\\|)',QUALIFIER),`GENE PRODUCT ID`]);stopifnot(length(ddr)==2660)
all<-list();ev<-list();rv<-list();diff<-list();quality<-list();cache<-new.env()
for(j in seq_len(nrow(u))){r<-u[j];gid<-as.integer(sub('KLA31_','',r$GroupID));path<-r$SourceFile;if(!startsWith(path,'/'))path<-file.path(rawroot,path)
 if(!exists(path,cache,inherits=FALSE)){x<-if(gid==5)as.data.table(read_excel(path,skip=12)) else if(gid==7)as.data.table(read_excel(path,skip=1)) else if(gid%in%c(3,4))as.data.table(read.delim(path,check.names=FALSE,quote='"',comment.char=''))else fread(path,quote='',check.names=FALSE);assign(path,x,cache)}else x<-get(path,cache)
 keep<-rep(TRUE,nrow(x));for(col in intersect(c('Reverse','Potential contaminant','Contaminant','Only identified by site'),names(x)))keep<-keep & !flag(x[[col]])
 if('id'%in%names(x))keep<-keep & !is.na(x$id)
 sid<-r$SampleID;cols<-character();field<-'';criterion<-''
 if(gid==1){field<-'Proteins';cols<-paste0('Reporter intensity corrected ',sub('RCT','',sid),'___',1:3);keep<-keep & pos(x[['Localization prob']]) & Reduce(`|`,lapply(cols,function(c)pos(x[[c]])));criterion<-'Kla site table; RCT reporter channel positive across multiplicity columns; global localization >0'}
 if(gid%in%c(2,6,10)){field<-'Proteins';cols<-paste('Localization prob',sid);keep<-keep & pos(x[[cols]]);criterion<-'Kla site table; sample localization >0; exclude reverse/contaminant/site-only rows'}
 if(gid%in%c(3,4)){field<-'Master Protein Accessions';cols<-names(x)[startsWith(names(x),'Found in Sample:')&(endsWith(names(x),paste0(', ',sid))|endsWith(names(x),paste0(', ',sid,'_1')))];stopifnot(length(cols)==1);v<-trimws(as.character(x[[cols]]));keep<-keep&grepl('Lacty|Lactyl|La \\(K\\)',x$Modifications,ignore.case=TRUE)&!is.na(v)&nzchar(v)&v!='Not Found';criterion<-'lactyl-modified PD peptide groups; detected sample category other than Not Found'}
 if(gid==5){field<-'Proteins accession';cols<-paste0('Intensity_',sid);keep<-keep & pos(x[[cols]]) & !is.na(x[['Positions within proteins']]);criterion<-'S3 Kla sites with protein positions and positive sample intensity'}
 if(gid==7){field<-'PTM.ProteinId';cols<-grep('^PTM.SiteProbability',names(x),value=TRUE);labels<-trimws(gsub('(^PTM.SiteProbability\\[|\\]$)','',cols));cols<-cols[labels==sid];stopifnot(length(cols)==1);keep<-keep&tolower(trimws(x$PTM.ModificationTitle))=='lactylation'&x$PTM.SiteAA=='K'&pos(x[[cols]]);criterion<-'author Kla PTM table; K; sample site probability >0'}
 if(gid%in%c(8,11)){field<-'PTM.ProteinId';cols<-'R.Condition';keep<-keep&x$R.Condition==sid&x$PTM.ModificationTitle=='L-Lac(K)'&x$PTM.SiteAA=='K'&pos(x$PTM.SiteProbability);criterion<-'condition-specific L-Lac(K), K, PTM site probability >0'}
 if(gid%in%c(9,12)){field<-'Protein accession';cols<-if(gid==9)'Intensity Control' else 'Intensity HCC';keep<-keep&pos(x[[cols]])&pos(x[['Localization probability']]);criterion<-'Kla site table; one tissue channel positive intensity and localization >0'}
 keep[is.na(keep)]<-FALSE
 a<-parse_new(x[[field]][keep]);o<-parse_old(x[[field]][keep]);cc<-cur[GroupID==r$GroupID&SampleID==sid,BaseAccession]
 all[[j]]<-data.table(GroupID=r$GroupID,Dataset='Lactylome (Kla)',SampleID=sid,BaseAccession=a,IsDdr=a%in%ddr,SourceFile=path)
 rv[[j]]<-data.table(GroupID=r$GroupID,SampleID=sid,SelectedSourceRows=sum(keep),Total=length(a),DDR=sum(a%in%ddr),Percent=100*mean(a%in%ddr),CurrentTotal=length(cc),CurrentDDR=r$DdrProteinCount,OldParserExact=setequal(o,cc),NewParserExact=setequal(a,cc),Added=length(setdiff(a,cc)),Removed=length(setdiff(cc,a)),Criterion=criterion)
 delta<-rbindlist(list(data.table(BaseAccession=setdiff(a,cc),Change='added'),data.table(BaseAccession=setdiff(cc,a),Change='removed')));if(nrow(delta)){delta[,`:=`(GroupID=r$GroupID,SampleID=sid)];diff[[j]]<-delta}
 val<-as.character(x[[field]][keep]);ev[[j]]<-data.table(GroupID=r$GroupID,SampleID=sid,SourceFile=path,Rows=nrow(x),AccessionField=field,DetectionColumns=paste(cols,collapse=';'),DetectedValues=paste(head(sort(unique(unlist(x[,..cols]))),12),collapse=' | '),SemicolonRows=sum(grepl(';',val)),CommaRows=sum(grepl(',',val)),ColonRows=sum(grepl(':',val)),PipeRows=sum(grepl('|',val,fixed=TRUE)),IsoformRows=sum(grepl('-[0-9]+($|[;,:|])',val)),TenCharIDs=sum(nchar(a)==10),ContaminantIDRows=sum(grepl('REV__|CON__|DECOY|CONTAM',val,ignore.case=TRUE)),FlagFields=paste(intersect(c('Reverse','Potential contaminant','Contaminant','Only identified by site'),names(x)),collapse=';'),ExampleAccessions=paste(head(unique(val[grepl('[;,:|]|-[0-9]+',val)]),4),collapse=' // '))
 interesting<-grep('decoy|contaminant|^PTM.SiteAA$|^PTM.ModificationTitle$|R.FileName|R.Replicate|R.Condition|R.Fraction|Found in Sample:|^Amino acid$',names(x),value=TRUE,ignore.case=TRUE)
 if(!r$SourceFile%in%vapply(quality,function(z)z$SourceFile[1],character(1))&&length(interesting))quality[[length(quality)+1]]<-rbindlist(lapply(interesting,function(z)data.table(SourceFile=r$SourceFile,Field=z,UniqueN=uniqueN(x[[z]]),Values=paste(head(unique(x[[z]]),30),collapse=' | '))))
}
a<-rbindlist(all);reviews<-rbindlist(rv);fwrite(a,file.path(out,'independent_membership.csv.gz'));fwrite(reviews,file.path(out,'sample_review.csv'));fwrite(rbindlist(ev),file.path(out,'source_evidence.csv'));fwrite(rbindlist(quality),file.path(out,'source_field_values.csv'));fwrite(rbindlist(diff),file.path(out,'membership_differences.csv'))
gr<-reviews[,.(Samples=.N,Mean=mean(Percent),SD=sd(Percent),SEM=sd(Percent)/sqrt(.N),AllOldParserMatch=all(OldParserExact),AllNewParserMatch=all(NewParserExact),Added=sum(Added),Removed=sum(Removed)),by=GroupID];gr[,Dataset:='Lactylome (Kla)'];fwrite(gr,file.path(out,'group_review.csv'));print(gr)
